import{_ as a,H as n,f as i,i as e}from"./chunks/framework.BH2BK_3i.js";const k=JSON.parse('{"title":"40 | 软件部署实战（上）：部署方案及负载均衡、高可用组件介绍","description":"","frontmatter":{},"headers":[{"level":2,"title":"部署方案","slug":"部署方案","link":"#部署方案","children":[]},{"level":2,"title":"Nginx安装和配置","slug":"nginx安装和配置","link":"#nginx安装和配置","children":[{"level":3,"title":"Nginx功能简介","slug":"nginx功能简介","link":"#nginx功能简介","children":[]},{"level":3,"title":"Nginx安装步骤","slug":"nginx安装步骤","link":"#nginx安装步骤","children":[]}]},{"level":2,"title":"Keepalived安装和配置","slug":"keepalived安装和配置","link":"#keepalived安装和配置","children":[{"level":3,"title":"Keepalived安装步骤","slug":"keepalived安装步骤","link":"#keepalived安装步骤","children":[]},{"level":3,"title":"Keepalived配置文件解析","slug":"keepalived配置文件解析","link":"#keepalived配置文件解析","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"课后练习","slug":"课后练习","link":"#课后练习","children":[]}],"relativePath":"Go语言项目开发实战/40-软件部署实战（上）：部署方案及负载均衡、高可用组件介绍.md","filePath":"Go语言项目开发实战/40-软件部署实战（上）：部署方案及负载均衡、高可用组件介绍.md","lastUpdated":1779815754000}'),p={name:"Go语言项目开发实战/40-软件部署实战（上）：部署方案及负载均衡、高可用组件介绍.md"};function l(t,s,d,h,c,o){return n(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="_40-软件部署实战-上-部署方案及负载均衡、高可用组件介绍" tabindex="-1">40 | 软件部署实战（上）：部署方案及负载均衡、高可用组件介绍 <a class="header-anchor" href="#_40-软件部署实战-上-部署方案及负载均衡、高可用组件介绍" aria-label="Permalink to &quot;40 | 软件部署实战（上）：部署方案及负载均衡、高可用组件介绍&quot;">​</a></h1><p>你好，我是孔令飞。</p><p>接下来，我们就进入到这门课的最后一个模块，服务部署部分的学习。在这一模块中，我会带着你一步一步地部署一个生产级可用的IAM应用。</p><p>在 <a href="https://time.geekbang.org/column/article/378082" target="_blank" rel="noreferrer">03讲</a> 中，我们快速在单机上部署了IAM系统，但这样的系统缺少高可用、弹性扩容等能力，是很脆弱的，遇到流量波峰、发布变更很容易出问题。在系统真正上线前，我们需要重新调整部署架构，来保证我们的系统具有负载均衡、高可用、弹性伸缩等核心运维能力。</p><p>考虑到你手中的系统资源有限，这一模块会尽量简单地展示如何部署一个相对高可用的IAM系统。按照我讲的部署方法，基本上可以上线一个中小型的系统。</p><p>在这一模块中，我会介绍两种部署方式。</p><p>第一种是传统的部署方式，基于物理机/虚拟机来部署，容灾、弹性伸缩能力要部署人员自己实现。第二种是容器化部署方式，基于Docker、Kubernetes来部署，容灾、弹性伸缩等能力，可以借助Kubernetes自带的能力来实现。</p><p>接下来的三讲，我们先来看下传统的部署方式，也就是如何基于虚拟机来部署IAM应用。今天我主要讲跟IAM部署相关的两个组件，Nginx + Keepalived的相关功能。</p><h2 id="部署方案" tabindex="-1">部署方案 <a class="header-anchor" href="#部署方案" aria-label="Permalink to &quot;部署方案&quot;">​</a></h2><p>先来整体看下我们的部署方案。</p><p>这里，我采用Nginx + Keepalived来部署一个高可用的架构，同时将组件都部署在内网，来保证服务的安全和性能。</p><p>部署需要两台物理机/虚拟机，组件之间通过内网访问。所需的服务器如下表所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%AF%AD%E8%A8%80%E9%A1%B9%E7%9B%AE%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/411663/e0a3323831768fbe7f45085ca4a53a1d.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%AF%AD%E8%A8%80%E9%A1%B9%E7%9B%AE%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/411663/e0a3323831768fbe7f45085ca4a53a1d.jpg" alt="图片"></a></p><p>两台服务器均为腾讯云CVM，VIP（Virtual IP，虚拟IP）为 <code>10.0.4.99</code>。部署架构如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%AF%AD%E8%A8%80%E9%A1%B9%E7%9B%AE%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/411663/fc5331a780d45a7de6223d6ff3c86f9d.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%AF%AD%E8%A8%80%E9%A1%B9%E7%9B%AE%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/411663/fc5331a780d45a7de6223d6ff3c86f9d.jpg" alt="图片"></a></p><p>这里我来具体介绍下图中的部署架构。部署采用的这两台CVM服务器，一主一备，它们共享同一个VIP。同一时刻，VIP只在一台主设备上生效，当主服务器出现故障时，备用服务器会自动接管VIP，继续提供服务。</p><p>主服务器上部署了 <code>iam-apiserver</code>、 <code>iam-authz-server</code>、 <code>iam-pump</code> 和数据库 <code>mongodb</code>、 <code>redis</code>、 <code>mysql</code>。备服务器部署了 <code>iam-apiserver</code>、 <code>iam-authz-server</code> 和 <code>iam-pump</code>。备服务器中的组件通过内网 <code>10.0.4.20</code> 访问主服务器中的数据库组件。</p><p>主备服务器同时安装了Keepalived和Nginx，通过Nginx的反向代理功能和负载均衡功能，实现后端服务 <code>iam-apiserver</code> 和 <code>iam-authz-server</code> 的高可用，通过Keepalived实现Nginx的高可用。</p><p>我们通过给虚拟IP绑定腾讯云弹性公网IP，从而使客户端可以通过外网IP访问内网的Nginx服务器（ <code>443</code> 端口），如果想通过域名访问内网，还可以申请域名指向该弹性公网IP。</p><p>通过以上部署方案，我们可以实现一个具有较高可用性的IAM系统，它主要具备下面这几个能力。</p><ul><li>高性能：可以通过Nginx的负载均衡功能，水平扩容IAM服务，从而实现高性能。</li><li>具备容灾能力：通过Nginx实现IAM服务的高可用，通过Keepalived实现Nginx的高可用，从而实现核心组件的高可用。</li><li>具备水平扩容能力：通过Nginx的负载均衡功能，实现IAM服务的水平扩容。</li><li>高安全性：将所有组件部署在内网，客户端只能通过 <code>VIP:443</code> 端口访问Nginx服务，并且通过开启TLS认证和JWT认证，保障服务有一个比较高的安全性。因为是腾讯云CVM，所以也可以借助腾讯云的能力再次提高服务器的安全性，比如安全组、DDoS防护、主机安全防护、云监控、云防火墙等。</li></ul><p>这里说明下，为了简化IAM应用的安装配置过程，方便你上手实操，有些能力，例如数据库高可用、进程监控和告警、自动伸缩等能力的构建方式，这里没有涉及到。这些能力的构建方式，你可以在日后的工作中慢慢学习和掌握。</p><p>接下来，我们看下这个部署方案中用到的两个核心组件，Nginx和Keepalived。我会介绍下它们的安装和配置方法，为你下一讲的学习做准备。</p><h2 id="nginx安装和配置" tabindex="-1">Nginx安装和配置 <a class="header-anchor" href="#nginx安装和配置" aria-label="Permalink to &quot;Nginx安装和配置&quot;">​</a></h2><h3 id="nginx功能简介" tabindex="-1">Nginx功能简介 <a class="header-anchor" href="#nginx功能简介" aria-label="Permalink to &quot;Nginx功能简介&quot;">​</a></h3><p>这里先简单介绍下Nginx。Nginx是一个轻量级、高性能、开源的HTTP服务器和反向代理服务器。IAM系统使用了Nginx反向代理和负载均衡的功能，下面我就来分别介绍下。</p><p>为什么需要反向代理呢？在实际的生产环境中，服务部署的网络（内网）跟外部网络（外网）通常是不通的，这就需要一台既能够访问内网又能够访问外网的服务器来做中转，这种服务器就是反向代理服务器。Nginx作为反向代理服务器，简单的配置如下：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server {</span></span>
<span class="line"><span>    listen      80;</span></span>
<span class="line"><span>    server_name  iam.marmotedu.com;</span></span>
<span class="line"><span>    client_max_body_size 1024M;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    location / {</span></span>
<span class="line"><span>        proxy_set_header Host $http_host;</span></span>
<span class="line"><span>        proxy_set_header X-Forwarded-Host $http_host;</span></span>
<span class="line"><span>        proxy_set_header X-Real-IP $remote_addr;</span></span>
<span class="line"><span>        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;</span></span>
<span class="line"><span>        proxy_pass  http://127.0.0.1:8080/;</span></span>
<span class="line"><span>        client_max_body_size 100m;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Nginx的反向代理功能，能够根据不同的配置规则转发到不同的后端服务器上。假如我们在IP为 <code>x.x.x.x</code> 的服务器上，用上面说的Nginx配置启动Nginx，当我们访问 <code>http://x.x.x.x:80/</code> 时，会将请求转发到 <code>http://127.0.0.1:8080/</code>。 <code>listen 80</code> 指定了Nginx服务器的监听端口， <code>proxy_pass http://127.0.0.1:8080/</code> 则指定了转发路径。</p><p>Nginx另一个常用的功能是七层负载均衡。所谓的负载均衡，就是指当Nginx收到一个HTTP请求后，会根据负载策略将请求转发到不同的后端服务器上。比如iam-apiserver部署在两台服务器A和B上，当请求到达Nginx后，Nginx会根据A和B服务器上的负载情况，将请求转发到负载较小的那台服务器上。</p><p>这里要求iam-apiserver是无状态的服务。Nginx有多种负载均衡策略，可以满足不同场景下的负载均衡需求。</p><h3 id="nginx安装步骤" tabindex="-1"><strong>Nginx安装步骤</strong> <a class="header-anchor" href="#nginx安装步骤" aria-label="Permalink to &quot;**Nginx安装步骤**&quot;">​</a></h3><p>接下来，我就来介绍下如何安装和配置Nginx。</p><p>我们分别在 <code>10.0.4.20</code> 和 <code>10.0.4.21</code> 服务器上执行如下步骤，安装Nginx。</p><p>在CentOS 8.x系统上，我们可以使用yum命令来安装，具体安装过程可以分为下面4个步骤。</p><p>第一步，安装Nginx：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span></code></pre></div><p>第二步，确认Nginx安装成功：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nginx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx/1.14.1</span></span></code></pre></div><p>第三步，启动Nginx，并设置开机启动：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span></code></pre></div><p>Nginx默认监听 <code>80</code> 端口，启动Nginx前要确保 <code>80</code> 端口没有被占用。当然，你也可以通过修改Nginx配置文件 <code>/etc/nginx/nginx.conf</code> 修改Nginx监听端口。</p><p>第四步，查看Nginx启动状态：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span></code></pre></div><p>输出中有 <code>active (running)</code> 字符串，说明成功启动。如果Nginx启动失败，你可以查看 <code>/var/log/nginx/error.log</code> 日志文件，定位错误原因。</p><h2 id="keepalived安装和配置" tabindex="-1">Keepalived安装和配置 <a class="header-anchor" href="#keepalived安装和配置" aria-label="Permalink to &quot;Keepalived安装和配置&quot;">​</a></h2><p>Nginx自带负载均衡功能，并且当Nginx后端某个服务器故障后，Nginx会自动剔除该服务器，将请求转发到可用的服务器，通过这种方式实现后端API服务的高可用。但是 Nginx是单点的，如果Nginx挂了，后端的所有服务器就都不能访问，所以在实际生产环境中，也需要对Nginx做高可用。</p><p>业界最普遍采用的方法是通过Keepalived对前端Nginx实现高可用。Keepalived + Nginx的高可用方案具有服务功能强大、维护简单等特点。</p><p>接下来，我们来看下如何安装和配置Keepalived。</p><h3 id="keepalived安装步骤" tabindex="-1">Keepalived安装步骤 <a class="header-anchor" href="#keepalived安装步骤" aria-label="Permalink to &quot;Keepalived安装步骤&quot;">​</a></h3><p>我们分别在 <code>10.0.4.20</code> 和 <code>10.0.4.21</code> 服务器上执行下面5个步骤，安装Keepalived。</p><p>第一步，下载Keepalived的最新版本（这门课安装了当前的最新版本 <code>2.1.5</code>）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://www.keepalived.org/software/keepalived-2.1.5.tar.gz</span></span></code></pre></div><p>第二步，安装Keepalived：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openssl-devel</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # keepalived依赖OpenSSL，先安装依赖</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xvzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keepalived-2.1.5.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keepalived-2.1.5</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./configure</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix=/usr/local/keepalived</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> make</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>第三步，配置Keepalived：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/keepalived</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 安装后，默认没有创建/etc/keepalived目录</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/keepalived/etc/keepalived/keepalived.conf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  /etc/keepalived/keepalived.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/keepalived/etc/sysconfig/keepalived</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/sysconfig/keepalived</span></span></code></pre></div><p>Keepalived的systemd uint配置，默认使用了 <code>/usr/local/keepalived/etc/sysconfig/keepalived</code> 作为其 <code>EnvironmentFile</code>，我们还需要把它修改为 <code>/etc/sysconfig/keepalived</code> 文件。编辑 <code>/lib/systemd/system/keepalived.service</code> 文件，设置 <code>EnvironmentFile</code>，值如下：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EnvironmentFile</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-/etc/sysconfig/keepalived</span></span></code></pre></div><p>第四步，启动Keepalived，并设置开机启动：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keepalived</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keepalived</span></span></code></pre></div><p>这里要注意，Keepalived启动时不会校验配置文件是否正确，所以我们要小心修改配置，防止出现意想不到的问题。</p><p>第五步，查看Keepalived的启动状态：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keepalived</span></span></code></pre></div><p>输出中有 <code>active (running)</code> 字符串，说明成功启动。Keepalived的日志保存在 <code>/var/log/messages</code> 中，你有需要的话可以查看。</p><h3 id="keepalived配置文件解析" tabindex="-1">Keepalived配置文件解析 <a class="header-anchor" href="#keepalived配置文件解析" aria-label="Permalink to &quot;Keepalived配置文件解析&quot;">​</a></h3><p>Keepalived的默认配置文件为 <code>/etc/keepalived/keepalived.conf</code>，下面是一个Keepalived配置：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 全局定义，定义全局的配置选项</span></span>
<span class="line"><span>global_defs {</span></span>
<span class="line"><span># 指定keepalived在发生切换操作时发送email，发送给哪些email</span></span>
<span class="line"><span># 建议在keepalived_notify.sh中发送邮件</span></span>
<span class="line"><span>  notification_email {</span></span>
<span class="line"><span>    acassen&amp;#64;firewall.loc</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  notification_email_from Alexandre.Cassen&amp;#64;firewall.loc # 发送email时邮件源地址</span></span>
<span class="line"><span>    smtp_server 192.168.200.1 # 发送email时smtp服务器地址</span></span>
<span class="line"><span>    smtp_connect_timeout 30 # 连接smtp的超时时间</span></span>
<span class="line"><span>    router_id VM-4-21-centos # 机器标识，通常可以设置为hostname</span></span>
<span class="line"><span>    vrrp_skip_check_adv_addr # 如果接收到的报文和上一个报文来自同一个路由器，则不执行检查。默认是跳过检查</span></span>
<span class="line"><span>    vrrp_garp_interval 0 # 单位秒，在一个网卡上每组gratuitous arp消息之间的延迟时间，默认为0</span></span>
<span class="line"><span>    vrrp_gna_interval 0 # 单位秒，在一个网卡上每组na消息之间的延迟时间，默认为0</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span># 检测脚本配置</span></span>
<span class="line"><span>vrrp_script checkhaproxy</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  script &quot;/etc/keepalived/check_nginx.sh&quot; # 检测脚本路径</span></span>
<span class="line"><span>    interval 5 # 检测时间间隔（秒）</span></span>
<span class="line"><span>    weight 0 # 根据该权重改变priority，当值为0时，不改变实例的优先级</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span># VRRP实例配置</span></span>
<span class="line"><span>vrrp_instance VI_1 {</span></span>
<span class="line"><span>  state BACKUP  # 设置初始状态为&#39;备份&#39;</span></span>
<span class="line"><span>    interface eth0 # 设置绑定VIP的网卡，例如eth0</span></span>
<span class="line"><span>    virtual_router_id 51  # 配置集群VRID，互为主备的VRID需要是相同的值</span></span>
<span class="line"><span>    nopreempt               # 设置非抢占模式，只能设置在state为backup的节点上</span></span>
<span class="line"><span>    priority 50 # 设置优先级，值范围0～254，值越大优先级越高，最高的为master</span></span>
<span class="line"><span>    advert_int 1 # 组播信息发送时间间隔，两个节点必须设置一样，默认为1秒</span></span>
<span class="line"><span># 验证信息，两个节点必须一致</span></span>
<span class="line"><span>    authentication {</span></span>
<span class="line"><span>      auth_type PASS # 认证方式，可以是PASS或AH两种认证方式</span></span>
<span class="line"><span>        auth_pass 1111 # 认证密码</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  unicast_src_ip 10.0.4.21  # 设置本机内网IP地址</span></span>
<span class="line"><span>    unicast_peer {</span></span>
<span class="line"><span>      10.0.4.20             # 对端设备的IP地址</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span># VIP，当state为master时添加，当state为backup时删除</span></span>
<span class="line"><span>  virtual_ipaddress {</span></span>
<span class="line"><span>    10.0.4.99 # 设置高可用虚拟VIP，如果是腾讯云的CVM，需要填写控制台申请到的HAVIP地址。</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  notify_master &quot;/etc/keepalived/keepalived_notify.sh MASTER&quot; # 当切换到master状态时执行脚本</span></span>
<span class="line"><span>    notify_backup &quot;/etc/keepalived/keepalived_notify.sh BACKUP&quot; # 当切换到backup状态时执行脚本</span></span>
<span class="line"><span>    notify_fault &quot;/etc/keepalived/keepalived_notify.sh FAULT&quot; # 当切换到fault状态时执行脚本</span></span>
<span class="line"><span>    notify_stop &quot;/etc/keepalived/keepalived_notify.sh STOP&quot; # 当切换到stop状态时执行脚本</span></span>
<span class="line"><span>    garp_master_delay 1    # 设置当切为主状态后多久更新ARP缓存</span></span>
<span class="line"><span>    garp_master_refresh 5   # 设置主节点发送ARP报文的时间间隔</span></span>
<span class="line"><span>    # 跟踪接口，里面任意一块网卡出现问题，都会进入故障(FAULT)状态</span></span>
<span class="line"><span>    track_interface {</span></span>
<span class="line"><span>      eth0</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  # 要执行的检查脚本</span></span>
<span class="line"><span>  track_script {</span></span>
<span class="line"><span>    checkhaproxy</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这里解析下配置文件，大致分为下面4个部分。</p><ul><li>global_defs：全局定义，定义全局的配置选项。</li><li>vrrp_script checkhaproxy：检测脚本配置。</li><li>vrrp_instance VI_1：VRRP实例配置。</li><li>virtual_server：LVS配置。如果没有配置LVS+Keepalived，就不用设置这个选项。这门课中，我们使用Nginx代替LVS，所以无需配置 <code>virtual_server</code>（配置示例中不再展示）。</li></ul><p>只有在网络故障或者自身出问题时，Keepalived才会进行VIP切换。但实际生产环境中，我们往往使用Keepalived来监控其他进程，当业务进程出故障时切换VIP，从而保障业务进程的高可用。</p><p>为了让Keepalived感知到Nginx的运行状况，我们需要指定 <code>vrrp_script</code> 脚本， <code>vrrp_script</code> 脚本可以根据退出码，判断Nginx进程是否正常， <code>0</code> 正常，非 <code>0</code> 不正常。当不正常时，Keepalived会进行VIP切换。为了实现业务进程的监控，我们需要设置 <code>vrrp_script</code> 和 <code>track_script</code>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vrrp_script checkhaproxy</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    script &quot;/etc/keepalived/check_nginx.sh&quot;</span></span>
<span class="line"><span>    interval 3</span></span>
<span class="line"><span>    weight -20</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>vrrp_instance test</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    track_script</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        checkhaproxy</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这里，我介绍下上面配置中的一些配置项。</p><ul><li>script：指定脚本路径。</li><li>interval：表示Keepalived执行脚本的时间间隔（秒）。</li><li>weight：检测权重，可以改变 <code>priority</code> 的值。例如， <code>-20</code> 表示检测失败时，优先级 <code>-20</code>，成功时不变。 <code>20</code> 表示检测成功时，优先级 <code>+20</code>，失败时不变。</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>今天我主要讲了跟IAM部署相关的两个组件，Nginx + Keepalived的相关功能。</p><p>我们可以基于物理机/虚拟机来部署IAM应用，在部署IAM应用时，需要确保整个应用具备高可用和弹性扩缩容能力。你可以通过Nginx的反向代理功能和负载均衡功能实现后端服务iam-apiserver和iam-authz-server的高可用，通过Keepalived实现Nginx的高可用，通过Nginx + Keepalived组合，来实现IAM应用的高可用和弹性伸缩能力。</p><h2 id="课后练习" tabindex="-1">课后练习 <a class="header-anchor" href="#课后练习" aria-label="Permalink to &quot;课后练习&quot;">​</a></h2><ol><li>Keepalived的主备服务器要接在同一个交换机上。思考下，如果交换机故障，如何实现整个系统的高可用？</li><li>iam-pump是有状态的服务，思考下，如何实现iam-pump的高可用？</li></ol><p>欢迎你在留言区与我交流讨论，我们下一讲见。</p>`,81)])])}const g=a(p,[["render",l]]);export{k as __pageData,g as default};
